package com.rork.vitahero.data

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import kotlinx.coroutines.runBlocking
import kotlinx.serialization.json.Json

/**
 * Re-schedules all VitaHero notifications after device reboot.
 * Reads persisted state to know which camps, appointments, and kids need reminders.
 */
class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != Intent.ACTION_BOOT_COMPLETED) return

        val storage = StorageService(context)
        val json = Json { ignoreUnknownKeys = true }
        val state = try {
            storage.load()
        } catch (_: Exception) { return }

        if (!state.isLoggedIn) return

        // Re-schedule camp reminders
        state.camps?.filter { it.status == "UPCOMING" }?.forEach { camp ->
            NotificationScheduler.scheduleCampReminder(context, camp.title, camp.date, camp.time)
        }

        // Re-schedule checkup reminders
        state.appointments.forEach { appt ->
            NotificationScheduler.scheduleCheckupReminder(context, appt.doctorName, appt.kidName, appt.date, appt.time)
        }

        // Re-schedule diet reminders
        state.kids.forEach { kid ->
            NotificationScheduler.scheduleDietReminder(context, kid.name, kid.id)
        }
    }
}

